buildGradleAdditions.insert:
dependencies {
	implementation(name: 'HelpBot-release-0.1.13', ext: 'aar')
	implementation 'androidx.appcompat:appcompat:1.6.1'
	implementation 'com.google.android.material:material:1.9.0'
}

repositories {
	flatDir {
		dirs 'src/main/libs'
	}
}

gameActivityImports.insert:
import com.example.HelpBot.HelpBot;
import com.example.HelpBot.core.HelpBotConfig;
import com.example.HelpBot.core.HelpBotInitCallback;
import com.example.HelpBot.core.HelpBotCallback;
import com.example.HelpBot.core.HelpBotErrorCode;
import java.util.HashMap;
import java.util.Map;

gameActivityClassAdditions.insert:
public void AndroidThunkJava_HelpBot_Install(String channelId, String domain) {
	final String fChannelId = channelId;
	final String fDomain = domain;

	runOnUiThread(new Runnable() {
		@Override
		public void run() {
			try {
				HelpBotConfig config = new HelpBotConfig.Builder()
					.channelId(fChannelId)
					.domain(fDomain)
					.fullPrivacyMode(false)
					.enableSseNotification(true)
					.initTimeout(30000)
					.webViewLoadTimeout(15000)
					.addCustomConfig("showTitleBar", true)
					.build();

				HelpBot.install(GameActivity.this, config, new HelpBotInitCallback() {
					@Override
					public void onInitSuccess() {
						// Using native callback if needed
					}

					@Override
					public void onInitFailure(HelpBotErrorCode code, String msg) {
					}

					@Override
					public void onInitStart() {}

					@Override
					public void onInitProgress(int progress, String msg) {}
				});
			} catch (Exception e) {
				e.printStackTrace();
			}
		}
	});
}

public void AndroidThunkJava_HelpBot_Login(String token) {
	final String fToken = token;
	runOnUiThread(new Runnable() {
		@Override
		public void run() {
			Map<String, Object> config = new HashMap<>();
			config.put("full_privacy_enabled", false);
			HelpBot.login(fToken, config, null);
		}
	});
}

public void AndroidThunkJava_HelpBot_ShowConversation() {
	runOnUiThread(new Runnable() {
		@Override
		public void run() {
			HelpBot.showConversation(GameActivity.this);
		}
	});
}
